import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WindowType;
import org.openqa.selenium.chrome.ChromeDriver;
import java.util.Set;

public class MultipleWindowsExample {
    public static void main(String[] args) throws InterruptedException {
        WebDriver driver = new ChromeDriver();
        driver.manage().window().maximize();

        // Open main window
        driver.get("https://www.selenium.dev");
        String mainWindow = driver.getWindowHandle();
        System.out.println("Main window: " + driver.getTitle());
        Thread.sleep(2000);

        // Open new tab (Selenium 4)
        driver.switchTo().newWindow(WindowType.TAB);
        driver.get("https://www.selenium.dev/documentation");
        System.out.println("New tab: " + driver.getTitle());
        Thread.sleep(2000);

        // Get all window handles
        Set<String> allWindows = driver.getWindowHandles();
        System.out.println("Total windows: " + allWindows.size());

        // Switch between all windows
        for (String window : allWindows) {
            driver.switchTo().window(window);
            System.out.println("Window title: " + driver.getTitle());
        }

        // Close current window (not main)
        driver.close();
        System.out.println("Closed documentation window");

        // Switch back to main window
        driver.switchTo().window(mainWindow);
        System.out.println("Back to main: " + driver.getTitle());

        driver.quit();
    }
}
```

**Key Operations:**
1. `newWindow(WindowType.TAB)` - Opens new tab (Selenium 4)
2. `newWindow(WindowType.WINDOW)` - Opens new window (Selenium 4)
3. Store main window handle before opening new windows
4. Use close() to close current window
5. Use quit() to close all windows and end session

