```java
import org.openqa.selenium.OutputType;
import org.openqa.selenium.TakesScreenshot;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.apache.commons.io.FileUtils;
import java.io.File;
import java.text.SimpleDateFormat;
import java.util.Date;

public class ScreenshotExample {
    public static void main(String[] args) throws Exception {
        WebDriver driver = new ChromeDriver();
        driver.manage().window().maximize();
        driver.get("https://www.selenium.dev");

        // Generate timestamp
        String timestamp = new SimpleDateFormat("yyyy-MM-dd_HH-mm-ss")
            .format(new Date());

        // Cast driver to TakesScreenshot
        TakesScreenshot screenshot = (TakesScreenshot) driver;

        // Capture screenshot as File
        File sourceFile = screenshot.getScreenshotAs(OutputType.FILE);

        // Create destination with timestamp
        File destFile = new File("screenshots/selenium_" + timestamp + ".png");

        // Create directory if not exists
        destFile.getParentFile().mkdirs();

        // Copy to destination
        FileUtils.copyFile(sourceFile, destFile);

        System.out.println("Screenshot saved: " + destFile.getAbsolutePath());

        driver.quit();
    }
}
```

**Output Types:**
- `OutputType.FILE` - Save to file system
- `OutputType.BYTES` - Get as byte array
- `OutputType.BASE64` - Get as Base64 string (for HTML reports)

