```java
import org.openqa.selenium.By;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;

public class ScrollingExample {
    public static void main(String[] args) throws InterruptedException {
        WebDriver driver = new ChromeDriver();
        driver.manage().window().maximize();
        driver.get("https://www.selenium.dev");

        // Cast to JavascriptExecutor
        JavascriptExecutor js = (JavascriptExecutor) driver;

        // 1. Scroll down by pixels
        js.executeScript("window.scrollBy(0, 500);");
        System.out.println("Scrolled down 500px");
        Thread.sleep(2000);

        // 2. Scroll to bottom of page
        js.executeScript("window.scrollTo(0, document.body.scrollHeight);");
        System.out.println("Scrolled to bottom");
        Thread.sleep(2000);

        // 3. Scroll to specific element
        WebElement footer = driver.findElement(By.tagName("footer"));
        js.executeScript("arguments[0].scrollIntoView(true);", footer);
        System.out.println("Scrolled to footer");
        Thread.sleep(2000);

        // 4. Scroll to top of page
        js.executeScript("window.scrollTo(0, 0);");
        System.out.println("Scrolled to top");
        Thread.sleep(2000);

        // 5. Scroll element to center of viewport
        WebElement element = driver.findElement(By.id("someElement"));
        js.executeScript("arguments[0].scrollIntoView({block: 'center'});", element);

        driver.quit();
    }
}
```

**Common Scrolling Methods:**
- `scrollBy(x, y)` - Scroll by pixels
- `scrollTo(x, y)` - Scroll to position
- `scrollIntoView(true)` - Scroll element to top
- `scrollIntoView({block: 'center'})` - Scroll to center

